import json,pathlib,collections,html,re
R=pathlib.Path('docs/audits/dark-mode')
raw=json.loads((R/'coverage.raw.json').read_text()); states=json.loads((R/'states.raw.json').read_text()); inv=json.loads((R/'source-inventory.json').read_text()); commit=raw['sourceCommit']
checks=[]
for s in states['states']:
 if s['kind']=='current':
  for x in s['measurements']['checks']:
   if not x['passes'] and not x['inactive'] and any(c.isalpha() for c in x['text']):checks.append(dict(state=s['id'],**x))
(R/'contrast-measurements.json').write_text(json.dumps({'method':'Computed foreground and ancestor-composited background. Opaque samples with no uncertainty are verified calculations; gradients, group opacity and root estimates are candidates requiring painted sampling. Hidden elements excluded in targeted states. Disabled and color emoji excluded from findings. Normal text 4.5:1; large text 3:1. Samples are not a complete accessibility certification.','samples':checks},indent=2))
routes=[]
for r in raw['routes']:
 routes.append({k:v for k,v in r.items() if k not in ['desktop','mobile'] }|{'desktopSummary':{'theme':r.get('desktop',{}).get('theme'),'overflow':r.get('desktop',{}).get('overflow')},'mobileSummary':{'theme':r.get('mobile',{}).get('theme'),'overflow':r.get('mobile',{}).get('overflow')}})
for route,original in zip(routes,raw['routes']):
 route['name']=original.get('desktop',{}).get('heading') or route['pattern']
 code=pathlib.Path(route['source']).read_text()
 route['majorVisualComponents']=list(dict.fromkeys(re.findall(r"from ['\"]@/components/([^'\"]+)",code)))
 route['reasonNotFullyReviewed']='Sitter-session fixture unavailable; only 404 state captured.' if route['pattern']=='/sitter/[token]' else 'Redirect alias; destination default captured.' if route['pattern'] in ['/collections/new','/settings','/users'] else 'Default state only; interactions not exhaustively traversed.'
 route['reviewedStates']=['initial route render']
 route['identifiedFindings']=['DM-002'] if route['pattern']=='/server' else ['DM-005','DM-006'] if route['pattern']=='/care' else ['DM-004','DM-007'] if route['pattern']=='/server/ai-curator' else ['DM-001'] if route['pattern']=='/' else []
coverage={'sourceCommit':commit,'version':raw['version'],'capturedAt':raw['capturedAt'],'viewports':{'desktop':'1440×900','mobile':'390×844'},'scope':'100 route templates discovered; two viewport initial captures per route. 96 initial-state reviews, 3 redirect aliases, 1 sitter interior gap. Conditional states listed separately; no claim that all interactions or records were reviewed.','routes':routes,'conditionalStates':[{k:v for k,v in s.items() if k!='measurements'} for s in states['states']],'components':{'sourceScanned':len(inv['components']),'runtimeFixtures':['DeploymentProgress (running, failed, completed)','PhotoFramingEditor','MetricChart','shared controls','CareCategoryBadge','PlantTagChip'],'limitation':'Static production component render with fictional props; no operational effects or hydration. All other component source scans are not runtime sign-off.'},'gaps':['Sitter session interior: fixture token belonged to care-sheet mode; 404 captured, not reviewed.','Live deployment agent, filesystem garbage collection, real notification delivery, uploads, native camera/picker, provider errors and destructive confirmation completion not exercised.','No Safari/Firefox/device hardware or screen-reader audit. Mobile route defaults captured, not every conditional state.','No end-to-end persistence, keyboard traversal of every workflow or all user permissions.','Initial-route contrast candidates may include closed-detail content; findings rely on targeted visible states or explicitly labeled estimates.']}
(R/'coverage.json').write_text(json.dumps(coverage,indent=2))
F=[]
def add(id,p,title,area,category,evidence,source,problem,change,accept,metric=None,proposal=None):
 F.append(dict(id=id,severity=p,title=title,area=area,category=category,current=evidence,source=source,problem=problem,proposal=change,acceptance=accept,measurement=metric,proposedImage=proposal,decision='pending'))
add('DM-001','P1','Activity badges lose their text','Dashboard','Contrast','screenshots/annotated/activity-chips.dark.annotated.jpg','app/page.tsx: activity-kind badge styles','Workflow, Exhibit and Condition resolved inherit ivory text on opaque pastel backgrounds.','Use paired semantic foreground/background tokens for each activity kind; retain icon and text labels.','All normal badge text ≥4.5:1 in both themes; check all activity kinds.',{'status':'Computed, opaque','ratios':'Workflow 1.10:1; Exhibit 1.12:1; Condition resolved 1.17:1','foreground':'#eee7d7','background':'#eef2ff / #fff1f2 / #ecfdf5'},'screenshots/proposed/dashboard.desktop.dark.proposed-B.jpg')
