# Add measured foundational pairs and explicit semantic roles to the palette proposal.
def luminance(h):
 rgb=[int(h.lstrip('#')[i:i+2],16)/255 for i in (0,2,4)]
 return sum((v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4)*w for v,w in zip(rgb,[.2126,.7152,.0722]))
def ratio(a,b):
 x,y=sorted([luminance(a),luminance(b)])
 return (y+.05)/(x+.05)
pairs=[('Primary text','#e7ebe3','#202722'),('Secondary text','#bbc6ba','#202722'),('Accent link','#8ebb91','#202722'),('Action label','#f1f6ee','#315c42'),('Focus vs canvas','#a0c69a','#151a17'),('Success text','#b5d4ad','#233425'),('Warning text','#f0d28f','#3c321e'),('Danger text','#ef9a8c','#3b2724'),('Info text','#b6d7ef','#233340')]
with (R/'proposed-palette.md').open('a') as out:
 out.write('\n## B: foundational semantic pairs\n\nCalculated opaque sRGB contrast; these pairs are proposals, not proof of every rendered component. Borders are decorative unless they identify a control; do not claim a decorative border AA pass.\n\n| Role | Foreground | Background | Contrast |\n|---|---|---|---|\n')
 for name,fg,bg in pairs:out.write(f'| {name} | `{fg}` | `{bg}` | {ratio(fg,bg):.2f}:1 |\n')
 out.write('\nCurrent values are recorded in source-inventory.json (light and dark tokens). B proposes inset #181e1a, elevated #263029, disabled text #929f93 (inactive only), selection #314c36 with #e7ebe3 text, chart series #8ebb91 / #f0d28f / #b6c5ee / #eab2c1, and shadow rgba(0,0,0,.28). Validate chart lines against every surface and use shape/labels in addition to color. Existing care/tag paired tokens should remain authoritative rather than adopting status colors blindly.\n')
with (R/'theme-inventory.md').open('a') as out:
 out.write('\nArchitecture: Next.js App Router with server and client React components; Tailwind utility styling and global CSS variables; Prisma/PostgreSQL. Existing verification includes TypeScript, purpose-specific check scripts and Playwright browser tooling. This audit uses the existing production build against an isolated fixture database. The audit does not change app/theme entrypoints or run external providers.\n')
